-- 6. plan_versions (7 linhas) — created_by/published_by/discarded_by omitidos
--    (nullable; nenhum usuario real e copiado para homologacao)
--    CORRIGIDO: inseridas como 'draft' (status real da producao vem na
--    Secao 7b, DEPOIS de plan_capability_values) -- tg_plan_capability_values_immutability()
--    so permite INSERT/UPDATE/DELETE em plan_capability_values quando a
--    plan_version referenciada esta em status 'draft'. ON CONFLICT DO NOTHING
--    (nao DO UPDATE status) para nao violar tg_plan_versions_immutability()
--    ("Cannot revert status X to draft") em reaplicacoes do seed.
-- ---------------------------------------------------------------------
-- 663b1fa6 (Gratuito) tem 3 versoes. plan_versions_single_draft_per_plan (indice
-- unico parcial: 1 unico draft por plan_id por vez) exige processa-las em
-- sequencia estrita: draft -> suas capability values -> status final -> só
-- então a próxima versão do mesmo plano pode virar draft.
UPDATE public.plan_versions SET status='retired' WHERE id='9fe2aaa8-6b3e-4f80-8aa0-a0139a0e62b6' AND status='draft';

UPDATE public.plan_versions SET status='retired' WHERE id='2816c271-7874-4116-9372-bac067972d3d' AND status='draft';


-- ---------------------------------------------------------------------
-- 7. plan_capability_values (127 linhas) — valores de capability por versao de plano
--    (updated_by omitido; nullable)
-- ---------------------------------------------------------------------
-- (capability values de 2816c271-... movidas para a Secao 6, logo apos essa
--  plan_version ser inserida como draft e antes de virar 'retired' -- ver nota ali)

-- ---------------------------------------------------------------------
-- 7b. Transicao de status das plan_versions para o status final existente
--     em producao (agora legal: cada versao ja esta 'draft' e suas
--     capabilities ja foram inseridas na Secao 7 acima). Guard "AND status='draft'"
--     torna cada UPDATE idempotente -- em reaplicacoes a versao ja nao esta
--     mais em 'draft', a condicao nao bate e a linha vira no-op.
--     tg_plan_versions_immutability() permite draft->published e
--     draft->retired diretamente (so bloqueia reverter para draft e
--     bloqueia qualquer mudanca a partir de 'discarded').
--     4c268b92-... (plano "Teste") permanece 'draft' em producao -- sem UPDATE.
-- ---------------------------------------------------------------------
-- (transicoes de 9fe2aaa8-... e 2816c271-... para 'retired' ja feitas na Secao 6,
--  logo apos cada uma ter suas capability values inseridas)
UPDATE public.plan_versions SET status='published' WHERE id='31bf4382-2f96-4d24-9fda-d1d53c1723ed' AND status='draft';
UPDATE public.plan_versions SET status='published' WHERE id='e2bc5840-8652-42ca-a85d-66a43cf06d6e' AND status='draft';
UPDATE public.plan_versions SET status='published' WHERE id='505610df-88ba-4dde-916a-b27c39c9d701' AND status='draft';
UPDATE public.plan_versions SET status='published' WHERE id='ad6f333a-d2c6-4f8e-a65a-1e82d6320d3a' AND status='draft';

